// Simplex Noise (http://en.wikipedia.org/wiki/Simplex_noise), a type of gradient noise
// that uses N+1 vertices for random gradient interpolation instead of 2^N as in regular
// latice based Gradient Noise.

// All noise functions here:
//
// https://www.shadertoy.com/playlist/fXlXzf&from=0&num=12

// xxhash (https://xxhash.com)
// This is an XXH32 algorithm specialized for 8 bytes (two floats)
float hash1(vec2 x)
{
    uvec2 t = floatBitsToUint(x);
    uint h = 0xc2b2ae3du * t.x + 0x165667b9u;
    h = (h << 17u | h >> 15u) * 0x27d4eb2fu;
    h += 0xc2b2ae3du * t.y;
    h = (h << 17u | h >> 15u) * 0x27d4eb2fu;
    h ^= h >> 15u;
    h *= 0x85ebca77u;
    h ^= h >> 13u;
    h *= 0xc2b2ae3du;
    h ^= h >> 16u;
    return uintBitsToFloat(h >> 9u | 0x3f800000u) - 1.0;
}

vec2 hash2(vec2 x) // improved hash using xxhash
{
    float k = 6.283185307 * hash1(x);
    return vec2(cos(k), sin(k));
}

float noise2( in vec2 p )
{
    const float K1 = 0.366025404; // (sqrt(3)-1)/2;
    const float K2 = 0.211324865; // (3-sqrt(3))/6;

	vec2  i = floor( p + (p.x+p.y)*K1 );
    vec2  a = p - i + (i.x+i.y)*K2;
    float m = step(a.y,a.x); 
    vec2  o = vec2(m,1.0-m);
    vec2  b = a - o + K2;
	vec2  c = a - 1.0 + 2.0*K2;
    vec3  h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
	vec3  n = h*h*h*vec3( dot(a,hash2(i+0.0)), dot(b,hash2(i+o)), dot(c,hash2(i+1.0))); // changed to h^3 [1]
    return dot( n, vec3(32.99) ); // analytic factor (= 2916*sqrt(2)/125)
}

// --------- original version -------------

vec2 hash( vec2 p ) // replace this by something better
{
	p = vec2( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)) );
	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}

float noise( in vec2 p )
{
    const float K1 = 0.366025404; // (sqrt(3)-1)/2;
    const float K2 = 0.211324865; // (3-sqrt(3))/6;

	vec2  i = floor( p + (p.x+p.y)*K1 );
    vec2  a = p - i + (i.x+i.y)*K2;
    float m = step(a.y,a.x); 
    vec2  o = vec2(m,1.0-m);
    vec2  b = a - o + K2;
	vec2  c = a - 1.0 + 2.0*K2;
    vec3  h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
	vec3  n = h*h*h*h*vec3( dot(a,hash(i+0.0)), dot(b,hash(i+o)), dot(c,hash(i+1.0)));
    return dot( n, vec3(70.0) );
}

// -----------------------------------------------

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 p = fragCoord.xy / iResolution.xy;

	vec2 uv = p*vec2(iResolution.x/iResolution.y,1.0) + iTime*0.25;

	float f = 0.0;
	if (p.y < 0.5) { // down: original version
        // left: value noise	
        if( p.x<0.6 )
        {
            f = noise( 16.0*uv );
        }
        // right: fractal noise (4 octaves)
        else	
        {
            uv *= 5.0;
            mat2 m = mat2( 1.6,  1.2, -1.2,  1.6 );
            f  = 0.5000*noise( uv ); uv = m*uv;
            f += 0.2500*noise( uv ); uv = m*uv;
            f += 0.1250*noise( uv ); uv = m*uv;
            f += 0.0625*noise( uv ); uv = m*uv;
        }
    }
    else { // up: improved version
        // left: value noise	
        if( p.x<0.6 )
        {
            f = noise2( 16.0*uv );
        }
        // right: fractal noise (4 octaves)
        else	
        {
            uv *= 5.0;
            mat2 m = mat2( 1.6,  1.2, -1.2,  1.6 );
            f  = 0.5000*noise2( uv ); uv = m*uv;
            f += 0.2500*noise2( uv ); uv = m*uv;
            f += 0.1250*noise2( uv ); uv = m*uv;
            f += 0.0625*noise2( uv ); uv = m*uv;
        }
    }

	f = 0.5 + 0.5*f;

    f *= smoothstep( 0.0, 0.005, abs(p.x-0.6) );	
    f *= smoothstep( 0.0, 0.005, abs(p.y-0.5) );	
	fragColor = vec4( vec3(pow(f, 1.0 / 2.2)), 1.0 ); // gamma correction
}

// [1] GUSTAVSON, S., 2005. Simplex noise demystified. Self-published tutorial. URL: https://www.researchgate.net/publication/216813608_Simplex_noise_demystified.
